*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");


//#include("../js/controlResize.js"); // 화면 리사이징

scwin.vScrenID = 'ULDBNS22000.xml';
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.processGp; //파일 연결 1, 파일 삭제 5, 정보수정 6
scwin.vDelParam = new Object();
scwin.vModParam = new Object();
scwin.gDelRowChk = false;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : bns_search
 * 설명       : 채권 마스터 SRI 목록 조회한다.
 ***********************************************/
scwin.bns_search = function() {
    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SISUDATE, edt_EISUDATE) == false) {
        return false;
    }
    dts_file.removeAll();
    var param = '';
    param += "&{P}STD_CD=" + txb_pSTD_CD.getValue(); //표준코드
    param += "&{P}ISU_KOR_NM=" + txb_pISU_KOR_NM.getValue(); //한글종목명
    param += "&{P}ISUR_CD=" + txb_pISUR_CD.getValue(); //발행기관코드
    param += "&{P}SRI_BND_TP_CD=" + $c.stf.getObjectValue(cmb_pSRI_BND_TP_CD); //SRI채권구분
    param += "&{P}SISUDATE=" + edt_SISUDATE.getValue(); //신청일시작일
    param += "&{P}EISUDATE=" + edt_EISUDATE.getValue(); //신청일종료일
    param += "&{P}SLISTDATE=" + edt_SLISTDATE.getValue(); //상장일시작일
    param += "&{P}ELISTDATE=" + edt_ELISTDATE.getValue(); //상장일종료일
    param += "&{P}V_CHK_DELIST=" + scwin.getChkValue(chb_DELIST); //상장폐지포함
    param += "&{P}V_CHK_REG_CANCL=" + scwin.getChkValue(chb_RegCancl); //등록취소건

    var dsNm = 'BNSSRI_APPL_LIST';
    var qryId = 'lds.stf.bnssri.select.sriBndMgtList';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_List, dsNm, qryId, param);
    $c.cm.ShowWin(grd_Grid);
};
scwin.getChkValue = function(obj) {
    return (obj.checked) ? "Y" : "N";
};


/********************************************** 
 * 함수명   : ins_detail
 * 설명       : 첨부파일 리스트 조회한다.
 ***********************************************/
scwin.ins_detail = function() {
    var row = dts_List.getRowPosition();
    var STD_CD = dts_List.getCellData(row, "STD_CD");
    var APPL_SEQ = dts_List.getCellData(row, "APPL_ISU_SEQ");
    var param = "";
    param += "&{P}V_STD_CD=" + STD_CD; //표준코드
    param += "&{P}V_APPL_ISU_SEQ="; //신청일련번호를 null로 조회하면 해당표준코드의 모든 첨부파일을 가져옴

    //종목정보
    var dsNm = 'BNSSRI_APPL_FILE_LIST';
    var qryId = 'lds.stf.bnssri.select.sriBndMgtFileList';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_file, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_SetComboCode
 * 설명       : 콤보데이터를 정의한다.
 ***********************************************/
scwin.fn_SetComboCode = function() {
    //기관코드
    var qryId = 'lds.stf.bnscommon.select.listInstCd';
    var dsNm = 'BNS_INST_INFO';
    var param = '&{P}V_INST_NM=';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_InstCd, dsNm, qryId, param);
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_SRI_BND_TP_CD, 'SRI_BND_TP_CD'); //SRI채권구분
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_SRI_BND_REF_RULE_TP_CD, 'SRI_BND_REF_RULE_TP_CD'); //SRI채권준거원칙
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_EXT_REVW_INST_CD, 'EXT_REVW_INST_CD'); //외부검토기관
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_SRI_BND_EXT_VALU_KIND_CD, 'SRI_BND_EXT_VALU_KIND_CD'); //외부검토종류코드
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_CORE_OTCM_INDIC_CD, 'CORE_OTCM_INDIC_CD'); //KPI
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_SRI_BND_CHG_CONTN_CD, 'SRI_BND_CHG_CONTN_CD'); //변경사항
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_SRI_BND_PROG_STAT_CD, 'SRI_BND_PROG_STAT_CD'); //진행상태
    $c.bns.fn_SetBnsCombo(scwin.vScrenID, dts_SUPLY_FND_USE_RPT_RND_TP_CD, 'SUPLY_FND_USE_RPT_RND_TP_CD'); //보고구분

    // 이것을 하지 않으면 그리드에서 코드와 명이 같이 보인다. 2022-07-19
    dts_CORE_OTCM_INDIC_CD.Reset();
    dts_SRI_BND_CHG_CONTN_CD.Reset();
    dts_SRI_BND_PROG_STAT_CD.Reset();
    dts_EXT_REVW_INST_CD.Reset();
    dts_SUPLY_FND_USE_RPT_RND_TP_CD.Reset();
};


/*************************
 * 함수명   : fn_FileDownload
 * 설명     : 파일 다운로드
 * argument : object
 *************************/
scwin.fn_FileDownload = function(row) {
    if (dts_file.getCellData(row, "ORGN_FILE_NM") == "") {
        return;
    } else {
        var url = "/bns/BnsAttachDocFileDownload.do";
        url += "?ATTACH_FILE_TP_CD=" + 2;
        url += "&ISUR_CD=" + dts_file.getCellData(row, "ISUR_CD");
        url += "&APPL_DD=" + dts_file.getCellData(row, "APPL_DD");
        url += "&APPL_TM=" + dts_file.getCellData(row, "APPL_TM");
        location.href = url;
    }
};



/********************************************** 
 * 함수명   : fn_ShowIsur
 * 설명       : 발행기관 팝업을 보여준다.
 ***********************************************/
scwin.fn_ShowIsur = function(selObj) {
    if (vsCoPopGb != "SCH") {
        if (vRowCount == 0) return;
    }
    vSelObj = selObj;
    scwin.fn_GetPar = fn_GetParIsurCd;
    scwin.fn_SetPar = fn_SetParIsurCd;
    $c.bns.fn_PopIsurSearch(selObj);
};


/********************************************** 
 * 함수명   : fn_GetParIsurCd
 * 설명       : 발행기관 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetParIsurCd = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: $c.stf.getObjectValue(vSelObj),
        ISUR_NM: $c.stf.getObjectValue(vSelObj)
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetParIsurCd
 * 설명       : 발행기관 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParIsurCd = function(arrPar) {
    if (vsCoPopGb == "SCH") {
        $c.stf.setObjectValue(txb_COM_NM, scwin.arrPar[0].ISUR_NM);
        $c.stf.setObjectValue(txb_pISUR_CD, scwin.arrPar[0].ISUR_CD);
    } else {
        var cbdata = "^ ," + scwin.arrPar[0].ISUR_CD + "^" + scwin.arrPar[0].ISUR_NM;
        vSelObj.CBData = cbdata;
        $c.stf.setObjectValue(vSelObj, scwin.arrPar[0].ISUR_CD);
    }
};



/********************************************** 
 * 함수명   : fn_GetFileUpLoad
 * 설명       : 파일업로드 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_GetFileUpLoad = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: scwin.vDelParam.ISUR_CD,
        STD_CD: scwin.vDelParam.STD_CD,
        APPL_ISU_SEQ: scwin.vDelParam.APPL_ISU_SEQ,
        FILE_TP_CD_LIST: scwin.vDelParam.FILE_TP_CD_LIST,
        SRI_BND_TP_CD: scwin.vDelParam.SRI_BND_TP_CD
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetFileUpLoad
 * 설명       : 파일업로드 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetFileUpLoad = function(arrPar) {
    if ("Y" == scwin.arrPar[0].FILE_UP) {
        $c.win.alert($c.stf.getMessageParam("MSG-0001"));

        //조회조건 설정
        //setObjectValue(edt_ApplStartDd, vCurDate);
        //setObjectValue(edt_ApplEndDd, vCurDate);
        //setObjectValue(txb_ApplIsurNm, arrPar[0].ISUR_NM);
        //조회
        //bns_search();
        dts_file.Reset();
    }
};


/******************************************************************* 
 * 함수명   : fn_PopFileUpLoad
 * 설명     : 파일 업로드 팝업을 보여준다.
 * argument : object
 *******************************************************************/
scwin.fn_PopFileUpLoad = async function(grdObj) {
    $c.bns.fn_SetPopupPos(grdObj, 'E');
    await $c.frame.CreateDialogFrame("ULDBNS22002", "/bnslistbzappl/ULDBNS22002.gfm", "ESG채권 파일업로드", obj_left, obj_top, 940, 270, "window");
};


/********************************************** 
 * 함수명   : fn_ModAttachFileTpCd
 * 설명       : 첨부파일구분코드 수정 팝업에 넘길 데이터를 정의한다.
 ***********************************************/
scwin.fn_ModAttachFileTpCd = function(arrPar) {
    scwin.arrPar[0] = {
        ISUR_CD: scwin.vModParam.ISUR_CD,
        APPL_DD: scwin.vModParam.APPL_DD,
        APPL_TM: scwin.vModParam.APPL_TM,
        FILE_TP_CD_LIST: scwin.vModParam.FILE_TP_CD_LIST,
        SRI_BND_TP_CD: scwin.vModParam.SRI_BND_TP_CD
    };
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};

/********************************************** 
 * 함수명   : fn_SetModAttachFileTpCd
 * 설명       : 첨부파일구분코드 수정 팝업에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetModAttachFileTpCd = function(arrPar) {
    if ("Y" == scwin.arrPar[0].MOD_YN) {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
        dts_file.Reset();
    }
};


/******************************************************************* 
 * 함수명   : fn_PopModAttachFileTpCd
 * 설명     : 첨부파일구분코드 수정 팝업을 보여준다.
 * argument : object
 *******************************************************************/
scwin.fn_PopModAttachFileTpCd = async function(grdObj) {
    $c.bns.fn_SetPopupPos(grdObj, 'E');
    await $c.frame.CreateDialogFrame("ULDBNS22001", "/bnslistbzappl/ULDBNS22001.gfm", "ESG채권 파일구분수정", obj_left, obj_top, 690, 490, "window");
};


/********************************************** 
 * 함수명   : fn_Del_File
 * 설명       : 파일 원본 삭제
 ***********************************************/
scwin.fn_Del_File = function() {
    if (scwin.gDelRowChk == false) {
        $c.win.alert("첨부파일을 선택하십시오!");
        return;
    }

    //신청별(SRI채권등록, 조달자금보고, 등록취소) 파일이 현재 1건인 경우는 삭제불가 - 0건이 될수 없도록 조치함
    var dsNm = 'BNS_COM_CD';
    var qryId = 'lds.stf.bnssri.select.sriBndMgtFileList.FileCnt';
    var param = "&{P}V_STD_CD=" + scwin.vDelParam.STD_CD;
    param += "&{P}V_APPL_ISU_SEQ=" + scwin.vDelParam.APPL_ISU_SEQ;
    dts_Temp.SyncLoad = true;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_Temp, dsNm, qryId, param);
    if (dts_Temp.getCellData(1, 'VALUE') == '1') {
        if (dts_Temp.getCellData(1, 'TEXT') == '1') {
            $c.win.alert("현재 ESG채권등록 신청에 연결된 파일이 '1개'입니다. \n\n삭제 할 수 없습니다.");
        } else if (dts_Temp.getCellData(1, 'TEXT') == '2') {
            $c.win.alert("현재 조달자금사용보고 신청에 연결된 파일이 '1개'입니다. \n\n삭제 할 수 없습니다.");
        } else if (dts_Temp.getCellData(1, 'TEXT') == '3') {
            $c.win.alert("현재 ESG채권 등록취소 신청에 연결된 파일이 '1개'입니다. \n\n삭제 할 수 없습니다.");
        }
        return;
    }
    if (!confirm("파일(원본)을 삭제하시겠습니까?")) return false;
    var url;
    url = "/bns/FileFaxConn.do?method=deleteFile";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
    url += "&ISUR_CD=" + scwin.vDelParam.ISUR_CD;
    url += "&APPL_DD=" + scwin.vDelParam.APPL_DD;
    url += "&APPL_TM=" + scwin.vDelParam.APPL_TM;
    url += "&FILE_FAX=" + 'ESG';
    dts_file.UseChangeInfo = "False";
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_file)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : fn_Save_Info
 * 설명       : 정보수정 처리
 ***********************************************/
scwin.fn_Save_Info = function(param_del_rsn) {
    //수정사유 팝업에서 가져옴
    if (param_del_rsn != '') {
        txb_DEL_RSN.setValue(param_del_rsn);
    }

    // dts_List의 현재 row만 데이터 복사
    $c.stf.CopyDataSet(dts_List, dts_detail, "copyHeader=yes,rowFrom=" + dts_List.getRowPosition() + ",rowCnt=1");
    if (!confirm("수정하시겠습니까?")) return false;
    var url;
    url = "/bns/IsuChgEtc.do?method=updateEsgBndEditBtn";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    url += "&TRANSTR_EMP_NO=" + js_emp_no;
    trs_Save.Action = $c.lc.fn_encodeNSession(url);
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput1=dts_detail,I:pInput2=dts_SlbDetail)";
    trs_Save.Post();
};


/********************************************** 
 * 함수명   : sri_SlbDetail
 * 설명       : SLB(지속가능연계채권) 상세정보 조회
 ***********************************************/
scwin.sri_SlbDetail = function() {
    //데이터를 우선 지우고 신청ID가 없으면 스탑
    dts_SlbDetail.removeAll();
    var row = dts_List.getRowPosition();
    p_APPL_SEQ = dts_List.getCellData(row, "APPL_ISU_SEQ");
    p_STD_CD = $c.stf.getObjectValue(txb_STD_CD);
    var param = "&{P}V_STD_CD=" + dts_List.getCellData(row, "STD_CD");
    param += "&{P}V_APPL_ISU_SEQ=" + p_APPL_SEQ;
    var dsNm = 'BNSSRI_APPL_SLB_MGT_DETAIL_LIST';
    var qryId = 'lds.stf.bnssri.select.slbMgtDetailList';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_SlbDetail, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : fn_DownExcelAll
 * 설명       : 상단그리드, 하단SLB세부내역 전체를 다운로드한다.
 ***********************************************/
scwin.fn_DownExcelAll = function() {
    if (dts_List.getTotalRow() < 1) {
        return;
    }
    if (!confirm("전체 내용(SLB세부내역포함)을 엑셀파일로 다운로드 하시겠습니까?")) {
        return;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SISUDATE, edt_EISUDATE) == false) {
        return false;
    }
    dts_DownExcelAll.removeAll();
    var param = '';
    param += "&{P}STD_CD=" + txb_pSTD_CD.getValue(); //표준코드
    param += "&{P}ISU_KOR_NM=" + txb_pISU_KOR_NM.getValue(); //한글종목명
    param += "&{P}ISUR_CD=" + txb_pISUR_CD.getValue(); //발행기관코드
    param += "&{P}SRI_BND_TP_CD=" + $c.stf.getObjectValue(cmb_pSRI_BND_TP_CD); //SRI채권구분
    param += "&{P}SISUDATE=" + edt_SISUDATE.getValue(); //신청일시작일
    param += "&{P}EISUDATE=" + edt_EISUDATE.getValue(); //신청일종료일
    param += "&{P}SLISTDATE=" + edt_SLISTDATE.getValue(); //상장일시작일
    param += "&{P}ELISTDATE=" + edt_ELISTDATE.getValue(); //상장일종료일
    param += "&{P}V_CHK_DELIST=" + scwin.getChkValue(chb_DELIST); //상장폐지포함
    param += "&{P}V_CHK_REG_CANCL=" + scwin.getChkValue(chb_RegCancl); //등록취소건

    var dsNm = 'BNSSRI_APPL_DOWN_EXCEL_ALL';
    var qryId = 'lds.stf.bnssri.select.sriBndMgtDownExcelAll';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DownExcelAll, dsNm, qryId, param);
};


/********************************************** 
 * 함수명   : bns_search_AFRPT
 * 설명       : 사후보고 내용 조회
 ***********************************************/
scwin.bns_search_AFRPT = function(pMap) {
    dts_AFRPT.removeAll();
    var param = '';
    param += "&{P}V_ISUR_CD=" + pMap.ISUR_CD; //표준코드
    param += "&{P}V_APPL_DD=" + pMap.APPL_DD; //표준코드
    param += "&{P}V_APPL_TM=" + pMap.APPL_TM; //표준코드
    param += "&{P}V_STD_CD=" + pMap.STD_CD; //표준코드
    param += "&{P}V_APPL_ISU_SEQ=" + pMap.APPL_ISU_SEQ; //표준코드

    var dsNm = 'BNSSRI_APPL_LIST';
    var qryId = 'lds.stf.bnssri.select.sriBndMgtList.AFRPT';
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_AFRPT, dsNm, qryId, param);

    //ShowWin(grd_Grid);

};




/******************************************************************* 
 * 함수명   : fn_PopSaveRsn
 * 설명     : 수정사유 팝업을 보여준다.
 * argument : object
 *******************************************************************/
scwin.fn_PopSaveRsn = async function(grdObj) {
    $c.bns.fn_SetPopupPos(grdObj, 'E');
    await $c.frame.CreateDialogFrame("ULDBNS22003", "/bnslistbzappl/ULDBNS22003.gfm", "수정사유", obj_left, obj_top, 470, 190, "window");
};


/******************************************************************* 
 * 함수명   : fn_PopPrcnm
 * 설명     : 처리자조회 팝업을 보여준다.
 * argument : object
 *******************************************************************/
scwin.fn_PopPrcnm = async function(grdObj) {
    $c.bns.fn_SetPopupPos(grdObj, 'E');
