scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.dts_AFRPT_OnLoadCompleted = function(rowcount) {
    if (rowcount > 0) {
        //한글금액표기
        $c.stf.setObjectValue(txb_AmtHan1, $c.bns.fn_ChgAmtToHan(dts_AFRPT.getCellData(rowcount, 'ISU_AMT')));
        $c.stf.setObjectValue(txb_AmtHan2, $c.bns.fn_ChgAmtToHan(dts_AFRPT.getCellData(rowcount, 'SUPLY_FND_USE_RPT_EXECUTE_AMT')));
        $c.stf.setObjectValue(txb_AmtHan3, $c.bns.fn_ChgAmtToHan(dts_AFRPT.getCellData(rowcount, 'EXECUTE_AMT_SUM')));
        $c.stf.setObjectValue(txb_AmtHan4, $c.bns.fn_ChgAmtToHan(dts_AFRPT.getCellData(rowcount, 'UNUSED_AMT')));
    } else {
        //한글표기 초기화
        txb_AmtHan1.setValue('');
        txb_AmtHan2.setValue('');
        txb_AmtHan3.setValue('');
        txb_AmtHan4.setValue('');
    }
};
scwin.dts_file_OnLoadCompleted = function(rowcount) {
    //사후보고 데이터 가져옴
