    scwin.vDelParam.ISUR_CD = dts_file.getCellData(dts_file.getRowPosition(), "ISUR_CD");
    scwin.vDelParam.APPL_DD = dts_file.getCellData(dts_file.getRowPosition(), "APPL_DD");
    scwin.vDelParam.APPL_TM = dts_file.getCellData(dts_file.getRowPosition(), "APPL_TM");
    scwin.vDelParam.STD_CD = dts_file.getCellData(dts_file.getRowPosition(), "STD_CD");
    scwin.vDelParam.APPL_ISU_SEQ = dts_file.getCellData(dts_file.getRowPosition(), "APPL_ISU_SEQ");
    scwin.bns_search_AFRPT(scwin.vDelParam);
};
