scwin.btn_FileUp_onclick = function() {
    if (dts_List.getTotalRow() == 0) return;
    scwin.vDelParam.ISUR_CD = dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD");
    scwin.vDelParam.STD_CD = dts_List.getCellData(dts_List.getRowPosition(), "STD_CD");
    scwin.vDelParam.APPL_ISU_SEQ = dts_List.getCellData(dts_List.getRowPosition(), "APPL_ISU_SEQ");
    scwin.vDelParam.SRI_BND_TP_CD = dts_List.getCellData(dts_List.getRowPosition(), "SRI_BND_TP_CD");

    //파일구분코드 전체를 구분자'#' 포함하여 전달
    var temp = '';
    for (var i = 1; i <= dts_file.getTotalRow(); i++) {
        temp += '#' + dts_file.getCellData(i, "FILE_TP_CD");
    }
    scwin.vDelParam.FILE_TP_CD_LIST = temp;
    scwin.fn_GetPar = fn_GetFileUpLoad;
    scwin.fn_SetPar = fn_SetFileUpLoad;
    scwin.fn_PopFileUpLoad(grd_file);
};
scwin.btn_Mod_onclick = function() {
    if (dts_file.getTotalRow() == 0) return;
    scwin.vModParam.ISUR_CD = dts_file.getCellData(dts_file.getRowPosition(), "ISUR_CD");
    scwin.vModParam.APPL_DD = dts_file.getCellData(dts_file.getRowPosition(), "APPL_DD");
    scwin.vModParam.APPL_TM = dts_file.getCellData(dts_file.getRowPosition(), "APPL_TM");
    scwin.vModParam.SRI_BND_TP_CD = dts_List.getCellData(dts_List.getRowPosition(), "SRI_BND_TP_CD");

    //파일구분코드 전체를 구분자'#' 포함하여 전달
    var temp = '';
    for (var i = 1; i <= dts_file.getTotalRow(); i++) {
        if (dts_file.getCellData(dts_file.getRowPosition(), "FILE_TP_CD") != dts_file.getCellData(i, "FILE_TP_CD")) {
            temp += '#' + dts_file.getCellData(i, "FILE_TP_CD");
        }
    }
    scwin.vModParam.FILE_TP_CD_LIST = temp;
    scwin.fn_GetPar = fn_ModAttachFileTpCd;
    scwin.fn_SetPar = fn_SetModAttachFileTpCd;
    scwin.fn_PopModAttachFileTpCd(grd_file);
};
