scwin.trs_Save_OnFail = function() {
    if (scwin.processGp == 1) {
        $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    }
    if (scwin.processGp == 5) {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
    }
    if (scwin.processGp == 6) {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
    }
};
scwin.trs_Save_OnSuccess = function() {
    if (scwin.processGp == 1) {
        $c.win.alert($c.stf.getMessageParam("MSG-0001"));
        dts_List.Reset();
        dts_file.Reset();
    }
    if (scwin.processGp == 5) {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
        //dts_List.Reset();
        dts_file.Reset();
    }
    if (scwin.processGp == 6) {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
        //dts_List.Reset();
        dts_file.Reset();
    }
};
scwin.btn_prcnm_onclick = function() {
